package com.reiko45.furniture.core.registry;

import com.reiko45.furniture.ReikosFurniture;
import net.minecraft.core.registries.Registries;
import net.minecraft.sounds.SoundEvent;
import net.neoforged.neoforge.registries.DeferredHolder;
import net.neoforged.neoforge.registries.DeferredRegister;

/**
 * The mod's own sound effects. The .ogg files are made by {@code tools/sounds/generate_sounds.py};
 * {@code sounds.json} and the subtitles are generated by runData.
 */
public final class ModSounds {
    public static final DeferredRegister<SoundEvent> SOUNDS = DeferredRegister.create(Registries.SOUND_EVENT, ReikosFurniture.MODID);

    public static final DeferredHolder<SoundEvent, SoundEvent> MICROWAVE_DING = register("microwave_ding");
    public static final DeferredHolder<SoundEvent, SoundEvent> TOILET_FLUSH = register("toilet_flush");
    public static final DeferredHolder<SoundEvent, SoundEvent> TV_STATIC = register("tv_static");
    public static final DeferredHolder<SoundEvent, SoundEvent> DOORBELL = register("doorbell");
    public static final DeferredHolder<SoundEvent, SoundEvent> WASHER_RUNNING = register("washer_running");
    public static final DeferredHolder<SoundEvent, SoundEvent> DRYER_RUNNING = register("dryer_running");
    public static final DeferredHolder<SoundEvent, SoundEvent> COFFEE_BREWING = register("coffee_brewing");
    public static final DeferredHolder<SoundEvent, SoundEvent> TOASTER_POP = register("toaster_pop");
    public static final DeferredHolder<SoundEvent, SoundEvent> BLENDER = register("blender");
    public static final DeferredHolder<SoundEvent, SoundEvent> WORKBENCH_SAW = register("workbench_saw");
    public static final DeferredHolder<SoundEvent, SoundEvent> ARCADE_BLIP = register("arcade_blip");
    public static final DeferredHolder<SoundEvent, SoundEvent> SLIDING_DOOR = register("sliding_door");
    public static final DeferredHolder<SoundEvent, SoundEvent> GLOBE_SPIN = register("globe_spin");
    public static final DeferredHolder<SoundEvent, SoundEvent> TOOLBOX_LATCH = register("toolbox_latch");
    public static final DeferredHolder<SoundEvent, SoundEvent> PROJECTOR = register("projector");
    public static final DeferredHolder<SoundEvent, SoundEvent> POPCORN_POPPING = register("popcorn_popping");
    public static final DeferredHolder<SoundEvent, SoundEvent> POTTERY_WHEEL = register("pottery_wheel");
    public static final DeferredHolder<SoundEvent, SoundEvent> SEWING_MACHINE = register("sewing_machine");

    /** English subtitles, keyed by sound name. */
    public static final java.util.Map<String, String> SUBTITLES = java.util.Map.ofEntries(
            java.util.Map.entry("microwave_ding", "Microwave beeps"),
            java.util.Map.entry("toilet_flush", "Toilet flushes"),
            java.util.Map.entry("tv_static", "TV crackles"),
            java.util.Map.entry("doorbell", "Doorbell rings"),
            java.util.Map.entry("washer_running", "Washing machine runs"),
            java.util.Map.entry("dryer_running", "Dryer tumbles"),
            java.util.Map.entry("coffee_brewing", "Coffee brews"),
            java.util.Map.entry("toaster_pop", "Toaster pops"),
            java.util.Map.entry("blender", "Blender whirs"),
            java.util.Map.entry("workbench_saw", "Saw cuts"),
            java.util.Map.entry("arcade_blip", "Arcade bleeps"),
            java.util.Map.entry("sliding_door", "Sliding door slides"),
            java.util.Map.entry("globe_spin", "Globe spins"),
            java.util.Map.entry("toolbox_latch", "Toolbox latch clicks"),
            java.util.Map.entry("projector", "Projector whirs"),
            java.util.Map.entry("popcorn_popping", "Popcorn pops"),
            java.util.Map.entry("pottery_wheel", "Pottery wheel spins"),
            java.util.Map.entry("sewing_machine", "Sewing machine rattles"));

    private ModSounds() {
    }

    private static DeferredHolder<SoundEvent, SoundEvent> register(String name) {
        return SOUNDS.register(name, () -> SoundEvent.createVariableRangeEvent(ReikosFurniture.id(name)));
    }
}
